import React from 'react';

import Navbar from '../Navbar/Navbar'

import HeaderST from '../../css/Header.module.css'

const Header = () => {
  return (
    <div className={HeaderST.header}>
      <div className='container'>
        <Navbar/>
      </div>
    </div>
  );
}

export default Header;
